// Builds seed/handbook/index.json from the handbook markdown files (scripts/build-handbook-index.ts and the
// staleness test both call this, so the committed index can be checked against the files).
import { parseHandbookEntry } from './parse';
import type { HandbookCategory, HandbookIndexFile, HandbookIndexItem } from './types';
import { HANDBOOK_CATEGORIES } from './types';

export const INDEX_FILE = 'index.json';
export const INDEX_NOTE =
  'Generated by scripts/build-handbook-index.ts from seed/handbook/*.md (run by npm run sync:seed). Do not edit.';

const CATEGORY_RANK = new Map<HandbookCategory, number>(HANDBOOK_CATEGORIES.map((c, i) => [c.id, i]));

export interface HandbookFile {
  file: string;
  markdown: string;
}

/** Parses every file; throws on a parse error, a parse warning or a duplicate id. */
export function buildHandbookIndex(files: readonly HandbookFile[]): HandbookIndexFile {
  const entries: HandbookIndexItem[] = [];
  const seen = new Map<string, string>();
  for (const { file, markdown } of files) {
    const e = parseHandbookEntry(markdown);
    if (e.warnings.length > 0) throw new Error(`${file}: ${e.warnings.join('; ')}`);
    const dup = seen.get(e.id);
    if (dup !== undefined) throw new Error(`${file}: id "${e.id}" is already used by ${dup}`);
    seen.set(e.id, file);
    const item: HandbookIndexItem = {
      id: e.id,
      file,
      title: e.title,
      category: e.category,
      order: e.order,
      signalIds: e.signalIds,
      keywords: e.keywords,
      sourceIds: e.sourceIds,
      summary: e.summary,
    };
    if (e.hazard !== undefined) item.hazard = e.hazard;
    if (e.protocolId !== undefined) item.protocolId = e.protocolId;
    if (e.experimental !== undefined) item.experimental = e.experimental;
    entries.push(item);
  }
  entries.sort(
    (a, b) =>
      (CATEGORY_RANK.get(a.category) ?? 99) - (CATEGORY_RANK.get(b.category) ?? 99) ||
      a.order - b.order ||
      a.id.localeCompare(b.id),
  );
  return { _note: INDEX_NOTE, entries };
}

/** Stable JSON text of the index file (2-space indent, trailing newline). */
export function serializeHandbookIndex(index: HandbookIndexFile): string {
  return `${JSON.stringify(index, null, 2)}\n`;
}
